// Maps a device's normalized reported name (status.name) to its product-art
// filename under public/devices/. Built by reconciling the provided art pack
// against each driver's actual reported name (the reconcile-mouse-art
// workflow, 567 verified pairs). Regenerate rather than editing entries.

/** lowercase, collapse every non-alphanumeric run to one space, trim. */
export function normDeviceName(name: string): string {
  return name.toLowerCase().replace(/[^a-z0-9]+/g, " ").trim();
}

